		if p.ProgressID > 0 && !p.Overwrite {
			// Resume existing snapshot progress record directly (no new row)
			var prev struct {
				LastSeenID    *string `gorm:"column:last_seen_id"`
				RowsProcessed int64   `gorm:"column:rows_processed"`
				Status        string  `gorm:"column:status"`
			}
			// Use SELECT FOR UPDATE to lock the row and prevent concurrent checks
			if err := tx.Raw(`
				SELECT last_seen_id, rows_processed, status
				FROM cdc_system.snapshot_progress
				WHERE id = ?
				FOR UPDATE
			`, p.ProgressID).Scan(&prev).Error; err != nil {
				return err
			}
			if prev.Status == "running" {
				return fmt.Errorf("snapshot progress %d is already running", p.ProgressID)
			}

			res := tx.Exec(`
				UPDATE cdc_system.snapshot_progress
				SET status = 'running',
				    trace_id = ?,
				    error_msg = NULL,
				    updated_at = NOW()
				WHERE id = ? AND status IN ('paused', 'error')
			`, p.TraceID, p.ProgressID)
			if res.Error != nil {
				return res.Error
			}
			if res.RowsAffected == 0 {
				return fmt.Errorf("failed to claim progress %d: status is not paused or error", p.ProgressID)
			}

